  const { metadata } = options
  // Compute row ranges to fetch
  const rowRanges = groupRanges(metadata, groupsHolding(metadata, rows))

  /** @type {(ParquetRow & {__index__: number})[]} */
  const sparseData = Array(Number(metadata.num_rows))
  if (!rowRanges.length) return sparseData

  // Fetch the ranges in parallel, then map the rows by position
  const rangeData = await Promise.all(rowRanges.map(([rangeStart, rangeEnd]) =>
    parquetReadObjects({ ...options, rowStart: rangeStart, rowEnd: rangeEnd })
  ))
  rowRanges.forEach(([rangeStart, rangeEnd], r) => {
    const groupData = rangeData[r]
    for (let i = rangeStart; i < rangeEnd; i++) {
      // warning: if the row contains a column named __index__, it will overwrite the index.
      sparseData[i] = { __index__: i, ...groupData[i - rangeStart] }
      if (options.includeRowIndex) {
        Object.defineProperty(sparseData[i], rowIndex, { value: groupData[i - rangeStart][rowIndex] })
      }
    }
  })
  return sparseData
}
